.sb-rail{display:grid;grid-auto-flow:column;grid-auto-columns:calc((100% - 40px)/3);gap:20px;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-color:#327d7d #122136;scrollbar-width:thin;padding:3px 1px 17px}.sb-rail:focus-visible{outline:2px solid #88ddce;outline-offset:4px;border-radius:12px}.sb-rail article.sb-card{padding:20px;margin:0;border:1px solid #4cdfb67d;border-radius:14px;background:radial-gradient(circle at 50% 29%,#20b79320,transparent 45%),linear-gradient(160deg,#122c35,#101829 70%);box-shadow:inset 0 1px #67ebc330,0 0 20px #38efbf08;scroll-snap-align:start;position:relative;display:flex;flex-direction:column;min-width:0;overflow:hidden}.sb-card:before{content:"";position:absolute;top:0;left:15%;right:15%;height:2px;background:#7dffe1;box-shadow:0 0 18px #51efca;pointer-events:none}.sb-card-top{display:flex;align-items:center;justify-content:space-between;gap:9px;min-height:22px}.sb-badge{color:#87f7d7;font-size:9px;font-weight:750;letter-spacing:.07em;white-space:nowrap}.sb-location{font-size:8px;color:#91acc5;text-align:right;line-height:1.5}.sb-logo{height:96px;display:flex;align-items:center;justify-content:center;margin-top:23px}.sb-logo img.teamlogo{height:87px;width:87px;object-fit:contain;background:transparent;padding:0;border-radius:0;filter:drop-shadow(0 5px 16px #0007)}.sb-card h3{text-align:center;font-size:23px;margin:12px 0 0;line-height:1.2}.sb-odds{text-align:center;font-size:70px;font-weight:750;letter-spacing:-.055em;line-height:1.18;margin:9px 0 0;color:#7bffdb;text-shadow:0 0 28px #4ef5c938}.sb-market{font-size:8px;letter-spacing:.14em;text-align:center;color:#91c7c5;margin-top:1px}.sb-card .sb-opponent{text-align:center;font-size:17px;color:#d8e5f3;margin:14px 0 22px;font-weight:650}.sb-model{display:grid;grid-template-columns:1fr 1fr;gap:9px;padding:14px 0;border-top:1px solid #60768a40;border-bottom:1px solid #60768a40}.sb-model>div:last-child{text-align:right}.sb-model small{font-size:8px;letter-spacing:.04em;color:#8cabc3;display:block}.sb-model b{font-size:22px;display:block;color:#e4f7fa;font-weight:600;margin-top:5px;white-space:nowrap}.sb-model b span{color:#708ba3}.sb-card .sb-reason{font-size:11px;line-height:1.7;color:#b3c9db;min-height:56px;margin:15px 0}.sb-card .sb-kickoff{font-size:10px;color:#a4b9cf;line-height:1.8;margin:0 0 16px}.sb-card button.sb-report{display:flex;justify-content:space-between;gap:15px;border:1px solid #66c9b255;background:#5cf4d10d;color:#a4f4df;padding:11px 13px;font-size:11px;border-radius:8px;margin-top:auto;width:100%}.sb-card button.sb-report:hover{background:#5cf4d122;border-color:#73d9bf}.sb-card button.sb-report:focus-visible{outline:2px solid #fff;outline-offset:3px}.sb-source{font-size:9px;line-height:1.6;color:#829eb6;margin:13px 0 0}.sb-coverage{font-size:10px;line-height:1.7;color:#8ca9bf;margin:13px 0 0}.sb-empty{padding:20px 0;color:#b6c5d8;font-size:13px;line-height:1.7}
